85	function mostrar(texto, tipo) {
86	  mensagem.textContent = texto;
87	  mensagem.className = tipo;
88	}
89	
90	function limparFormulario() {
91	  campos.id.value = '';
92	  campos.id.disabled = false;
93	  campos.nome.value = '';
94	  campos.frases.value = '';
95	  campos.resposta.value = '';
96	  campos.argumentos.value = '';
97	  campos.tentativas.value = 2;
98	  mensagem.className = '';
99	}
100	
101	function preencherFormulario(ficha) {
102	  // Não mexe em `mensagem` aqui: `salvar()` chama esta função logo depois de mostrar o
103	  // resultado, e limpar a classe agora escondia "Publicado."/"Rascunho salvo." na hora que
104	  // deveria aparecer. Quem troca de ficha na lista limpa a mensagem explicitamente.
105	  campos.id.value = ficha.id;
106	  campos.id.disabled = true;
107	  campos.nome.value = ficha.nome || '';
108	  campos.frases.value = (ficha.frases_do_lead || []).join('\n');
109	  campos.resposta.value = ficha.resposta_orientada || '';
110	  campos.argumentos.value = (ficha.argumentos_permitidos || []).join('\n');
111	  campos.tentativas.value = ficha.tentativas_antes_do_corretor || 2;
112	}
