114	async function carregarLista() {
115	  const resposta = await fetch('/api/objecoes');
116	  const fichas = await resposta.json();
117	  lista.innerHTML = '';
118	  for (const ficha of fichas) {
119	    const item = document.createElement('li');
120	    item.textContent = ficha.nome || ficha.id;
121	    const selo = document.createElement('span');
122	    selo.className = 'badge ' + ficha.status;
123	    selo.textContent = ficha.status;
124	    item.appendChild(selo);
125	    item.addEventListener('click', () => {
126	      mensagem.className = '';
127	      preencherFormulario(ficha);
128	    });
129	    lista.appendChild(item);
130	  }
131	}
132	
133	async function salvar(status) {
134	  const dados = {
135	    id: campos.id.value.trim(),
136	    nome: campos.nome.value,
137	    frases_do_lead: campos.frases.value.split('\n').map(l => l.trim()).filter(Boolean),
138	    resposta_orientada: campos.resposta.value,
139	    argumentos_permitidos: campos.argumentos.value.split('\n').map(l => l.trim()).filter(Boolean),
140	    tentativas_antes_do_corretor: Number(campos.tentativas.value),
141	    status: status,
142	  };
143	  if (!dados.id) {
144	    mostrar('Preencha o id da ficha.', 'erro');
145	    return;
146	  }
147	  const resposta = await fetch('/api/objecoes/' + encodeURIComponent(dados.id), {
148	    method: 'PUT',
149	    headers: { 'Content-Type': 'application/json' },
150	    body: JSON.stringify(dados),
151	  });
152	  const corpo = await resposta.json();
153	  if (!resposta.ok) {
154	    mostrar(corpo.erro || 'não foi possível salvar', 'erro');
155	    return;
156	  }
157	  mostrar(status === 'publicado' ? 'Publicado.' : 'Rascunho salvo.', 'sucesso');
